---
---
// ---------------------------------------------
// App Color & Typography Tokens (Adapted)
// ---------------------------------------------
$bg-app:      #7B68A6;
$paper:       #ffffff;
$paper-alt:   #f8fafc; 
$ink:         #0f172a;
$ink-soft:    #64748b;
$accent-title: #7ED8D1;
$hairline:    #e2e8f0;

$body:        -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
$mono:        "SFMono-Regular", Consolas, "Liberation Mono", Menlo, monospace;

// ---------------------------------------------
// Day / night theme variables
// Cards (hero/features/how/cta) stay white with dark ink text in both
// themes, so only the page background, header, footer, and accents need
// to swap — that's what keeps text readable through the transition.
// ---------------------------------------------
:root {
  --bg-start:      #FCE2EA; // soft pink
  --bg-end:        #F6C9DC; // slightly deeper pink
  --header-bg:     rgba(252, 226, 234, 0.85); // solid fallback before the image loads
  --header-tint:   rgba(252, 226, 234, 0.45); // lighter wash over the header image
  --header-border: rgba(15, 23, 42, 0.12);
  --nav-text:      #{$ink};
  --toggle-color:  #{$ink};
  --footer-text:   #{$ink};
  --footer-muted:  rgba(15, 23, 42, 0.65);
  --accent:        #{$accent-title};
}

html[data-theme="night"] {
  --bg-start:      #7B68A6; // the purple that used to be the fixed header color
  --bg-end:        #7B68A6; // flat, same purple throughout
  --header-bg:     rgba(123, 104, 166, 0.92); // solid fallback before the image loads
  --header-tint:   rgba(70, 58, 96, 0.55); // lighter wash over the header image
  --header-border: rgba(255, 255, 255, 0.2);
  --nav-text:      #ffffff;
  --toggle-color:  #ffffff;
  --footer-text:   #F1EEFB;
  --footer-muted:  rgba(241, 238, 251, 0.65);
  --accent:        #{$accent-title};
}

html, body {
  transition: background-color 0.6s ease, color 0.6s ease;
}

// ---------------------------------------------
// Reset & Base
// ---------------------------------------------
* { box-sizing: border-box; }
html { scroll-behavior: smooth; }

body {
  margin: 0;
  background-color: var(--bg-start); // shows instantly, before the image loads
  background-image: url("data:image/jpeg;base64,");
  background-size: cover;
  background-position: center;
  background-attachment: fixed;
  background-repeat: no-repeat;
  color: $ink;
  font-family: $body;
  font-size: 16px;
  line-height: 1.7;
  -webkit-font-smoothing: antialiased;

  &.modal-open { overflow: hidden; }
}

html[data-theme="night"] body {
  background-image: url("data:image/jpeg;base64,");
}

.wrap {
  max-width: 1080px;
  margin: 0 auto;
  padding: 0 32px;
}

h1, h2, h3 {
  font-family: $body;
  font-weight: 700;
  line-height: 1.15;
  margin: 0 0 16px;
  color: $ink;
}

h1 { font-size: clamp(2.1rem, 4.4vw, 3.2rem); }
h2 { font-size: clamp(1.6rem, 3vw, 2.2rem); }
h3 { font-size: 1.15rem; margin-bottom: 8px; } // Increased heading sizes

p { margin: 0 0 16px; color: $ink; }
.muted { color: $ink-soft; }

a { color: #2563eb; text-decoration: none; }

.divider {
  border: none;
  border-top: 1px solid $hairline;
  margin: 0;
}

// ---------------------------------------------
// Signature element: stamp tags
// ---------------------------------------------
.stamp {
  display: inline-block;
  font-family: $mono;
  font-size: 0.72rem;
  letter-spacing: 0.09em;
  text-transform: uppercase;
  color: #7c3aed;
  border: 1px solid #7c3aed;
  outline: 1px solid #7c3aed;
  outline-offset: 2px;
  padding: 5px 10px;
  transform: rotate(-1deg);
  margin-bottom: 20px;

  &--muted {
    color: $ink-soft;
    border-color: $hairline;
    outline-color: $hairline;
  }
}

// ---------------------------------------------
// Header & Nav (Bigger text & Logo integration)
// ---------------------------------------------
.site-header {
  position: sticky;
  top: 0;
  z-index: 10;
  background-color: var(--header-bg); // fallback before the image loads
  background-image: url("data:image/jpeg;base64,");
  background-size: cover;
  background-position: center;
  background-attachment: fixed;
  background-repeat: no-repeat;
  backdrop-filter: blur(6px);
  border-bottom: 1px solid var(--header-border);
  transition: background-color 0.6s ease, border-color 0.6s ease;
  overflow: visible !important;
}

html[data-theme="night"] .site-header {
  background-image: url("data:image/jpeg;base64,");
}

.site-header__row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 76px;
}

.wordmark-container {
  display: flex;
  align-items: center;
  gap: 12px;
  text-decoration: none;
}

.site-logo {
  height: 90px;
  width: auto;
  object-fit: contain;
  position: relative;
  top: 15px;
  transform: rotate(15deg);
  z-index: 11; // sit above the sticky header's own stacking context
}

.wordmark {
  font-family: $body;
  font-weight: 900;
  font-size: 1.8rem; 
  color: $accent-title !important;
  text-decoration: none;
  text-shadow: -1px 1px 0px #333, -2px 2px 0px #333;

  &--small { margin: 0 0 4px; font-size: 1.1rem; text-shadow: none; }
}

.site-nav {
  display: flex;
  align-items: center;
  gap: 28px;

  a {
    color: var(--nav-text);
    text-decoration: none;
    font-size: 0.95rem; /* Reverted nav text size */
    font-weight: 500;
    transition: color 0.6s ease;
  }
  a:hover { color: $accent-title; }

  &__cta {
    color: #000000 !important;
    background: #ffbe0b;
    border: 2px solid #000000;
    padding: 6px 14px;
    font-size: 0.85rem !important; /* Reverted download CTA size */
    border-radius: 4px;
  }
}

.theme-toggle {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 34px;
  height: 34px;
  padding: 0;
  border: 2px solid var(--toggle-color);
  border-radius: 50%;
  background: transparent;
  color: var(--toggle-color);
  cursor: pointer;
  font-size: 1rem;
  line-height: 1;
  transition: background 0.15s ease, transform 0.15s ease, color 0.6s ease, border-color 0.6s ease;

  &:hover { background: rgba(125, 104, 166, 0.15); }
  &:active { transform: scale(0.92); }

  &__icon { display: none; }
}

// sun shows by day, moon shows by night
html[data-theme="day"] .theme-toggle__icon--sun { display: inline; }
html[data-theme="night"] .theme-toggle__icon--moon { display: inline; }

// ---------------------------------------------
// Hero & Logo Image Replacement
// ---------------------------------------------
.hero { padding: 88px 0 64px; background: #ffffff; border-radius: 12px; margin: 20px auto; box-shadow: 0 4px 15px rgba(0,0,0,0.05); }

.hero__row {
  display: grid;
  grid-template-columns: 1.1fr 0.9fr;
  gap: 56px;
  align-items: center;
}

.hero-main-logo {
  max-width: 100% !important;
  height: auto !important;
  max-height: 180px !important;
}

.hero__lede {
  font-size: 1.15rem;
  color: $ink-soft;
  max-width: 44ch;
}

.button-row {
  display: flex;
  flex-wrap: wrap;
  gap: 16px;
  margin: 24px 0 14px;

  &--center {
    justify-content: center;
    margin: 20px 0 0;
  }
}

// ---------------------------------------------
// App Neo-Brutalist Buttons Integration
// ---------------------------------------------
.button {
  font-family: 'Impact', 'Arial Black', sans-serif !important; 
  text-transform: none;
  font-weight: 900 !important; 
  font-size: 16px !important;
  letter-spacing: 0.05em;
  padding: 12px 20px !important; 
  cursor: pointer; 
  text-align: center; 
  text-decoration: none;
  border: 3px solid #000000 !important;
  border-radius: 4px 11px 4px 11px / 11px 4px 11px 4px !important;
  box-shadow: -6px 6px 0px 0px #000000 !important;
  color: #000000 !important; 
  position: relative;
  transition: all 0.1s ease-in-out;
  display: inline-block;

  &--primary, &.button--load { background: #ffbe0b !important; }
  &--secondary, &.button--local { background: #e1dcbe !important; }
  &--sync { background: #4cc9f0 !important; }
  &--tux { background: #f4f4f4 !important; }

  &--demo {
    background: transparent !important;
    box-shadow: none !important;
    border: 3px solid #000000 !important;
    padding: 8px 18px !important;
    font-size: 14px !important;
  }

  &--on-dark {
    background: #ffbe0b !important;
    color: #000000 !important;
  }
  &--outline {
    background: #e1dcbe !important;
    color: #000000 !important;
  }

  &:hover { 
    transform: translate(-2px, 2px); 
    box-shadow: -4px 4px 0px 0px #000000 !important; 
  }
  &:active { 
    transform: translate(-6px, 6px); 
    box-shadow: 0px 0px 0px 0px #000000 !important; 
  }
}

.fine-print {
  font-family: $mono;
  font-size: 0.75rem;
  letter-spacing: 0.02em;
  color: $ink-soft;
  margin: 0;
}

// ---------------------------------------------
// App Screenshot Preview Frame (Replaces CSS mock window)
// ---------------------------------------------
.app-screenshot-frame {
  background: #F7F6F2;
  border: 2px solid #000000;
  box-shadow: -8px 8px 0px 0px rgba(0,0,0,0.8);
  transform: rotate(1deg);
  border-radius: 8px;
  overflow: hidden;
  display: flex;
}

.app-screenshot {
  width: 100%;
  height: auto;
  display: block;
}

// ---------------------------------------------
// Content Section Cards (Features & How It Works)
// ---------------------------------------------
.features, .how {
  background: #ffffff;
  padding: 60px 0;
  margin: 20px auto;
  border-radius: 12px;
  max-width: 1080px;
  box-shadow: 0 4px 15px rgba(0,0,0,0.05);
}

.eyebrow {
  font-family: $mono;
  font-size: 0.78rem; 
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: $ink-soft;
  margin-bottom: 28px;
}

.features__grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 40px 48px;
  padding: 0 32px;
}

.feature-card {
  padding: 24px;
  border: 1px solid $hairline;
  border-radius: 8px;
  background: #f8fafc;
}
.feature-card p { color: $ink-soft; }

.how__grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 30px;
  padding: 0 32px;
}

.how-step {
  padding: 24px;
  border: 1px solid $hairline;
  border-radius: 8px;
  background: #f8fafc;
}

.how-step__index {
  display: block;
  font-family: $mono;
  color: #7c3aed;
  font-size: 0.85rem; 
  letter-spacing: 0.08em;
  margin-bottom: 10px;
}

.how-step p { color: $ink-soft; }

// ---------------------------------------------
// CTA band
// ---------------------------------------------
.cta {
  background: #ffffff;
  color: $ink;
  padding: 64px 0;
  margin: 20px auto;
  border-radius: 12px;
  box-shadow: 0 4px 15px rgba(0,0,0,0.05);
}

.cta h2, .cta p { color: $ink; }

.cta__row {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 28px;
  padding: 0 32px;
}

// ---------------------------------------------
// Footer
// ---------------------------------------------
.site-footer {
  padding: 30px 0 50px;
  color: var(--footer-text);
  transition: color 0.6s ease;
}

.site-footer .muted {
  color: var(--footer-muted);
}

.site-footer__row {
  display: flex;
  flex-wrap: wrap;
  justify-content: space-between;
  gap: 24px;
}

.site-footer__contact a {
  font-family: $mono;
  font-size: 0.95rem;
  color: $accent-title;
}

// ---------------------------------------------
// Scroll reveal
// ---------------------------------------------
.reveal {
  opacity: 0;
  transform: translateY(28px);
  transition: opacity 0.7s ease, transform 0.7s ease;

  &.is-visible {
    opacity: 1;
    transform: none;
  }

  @for $i from 1 through 4 {
    &--stagger-#{$i}.is-visible {
      transition-delay: #{$i * 0.08}s;
    }
  }
}

// ---------------------------------------------
// Demo video modal
// ---------------------------------------------
.modal {
  position: fixed;
  inset: 0;
  z-index: 100;
  display: none;
  align-items: center;
  justify-content: center;
  padding: 24px;

  &.is-open { display: flex; }
}

.modal__backdrop {
  position: absolute;
  inset: 0;
  background: rgba(15, 10, 30, 0.72);
  animation: modal-fade 0.2s ease;
}

.modal__panel {
  position: relative;
  z-index: 1;
  width: 100%;
  max-width: 860px;
  background: #000000;
  border: 3px solid #000000;
  border-radius: 8px;
  box-shadow: -8px 8px 0px 0px rgba(0, 0, 0, 0.5);
  animation: modal-pop 0.25s ease;
  overflow: hidden;
}

.modal__close {
  position: absolute;
  top: 8px;
  right: 8px;
  z-index: 2;
  width: 34px;
  height: 34px;
  border: 2px solid #000000;
  border-radius: 50%;
  background: #ffbe0b;
  color: #000000;
  font-size: 1.3rem;
  line-height: 1;
  cursor: pointer;
}

.modal__video {
  position: relative;
  width: 100%;
  aspect-ratio: 16 / 9;
  background: #000000;

  iframe {
    position: absolute;
    inset: 0;
    width: 100%;
    height: 100%;
    border: 0;
  }
}

.modal__placeholder {
  height: 100%;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  text-align: center;
  color: #ffffff;
  padding: 24px;

  p { color: #ffffff; }
  code {
    background: rgba(255, 255, 255, 0.12);
    padding: 2px 6px;
    border-radius: 4px;
  }
}

@keyframes modal-fade {
  from { opacity: 0; }
  to { opacity: 1; }
}

@keyframes modal-pop {
  from { opacity: 0; transform: scale(0.96); }
  to { opacity: 1; transform: scale(1); }
}

// ---------------------------------------------
// Responsive Queries
// ---------------------------------------------
@media (max-width: 860px) {
  .hero__row { grid-template-columns: 1fr; }
  .features__grid { grid-template-columns: 1fr; }
  .how__grid { grid-template-columns: 1fr; }
  .site-nav { gap: 16px; }
}

@media (prefers-reduced-motion: reduce) {
  html { scroll-behavior: auto; }
  .button { transition: none; }
  .reveal { transition: none; }
  .modal__backdrop, .modal__panel { animation: none; }
  html, body, .site-header, .site-footer { transition: none; }
}

@media (max-width: 480px) {
  .button-row--center { width: 100%; }
}